import { ROUTES } from './workspace-routes.js';
import { attachStatisticsRefresh } from './refresh.js';
import { readStatisticsOverview } from './overview-contract.js';
const CHARACTER_NAMES=['기사','무투가','학살자','총잡이','마도사','방랑 용병','사냥꾼','낭인','늑대인간','소환술사','암살자','수호자','약탈자','주술사','용인','소울이터','흡혈귀','얀델','도플갱어','승부사','이단심판관','광전사'];
const CHARACTER_IMAGE_IDS=new Map(CHARACTER_NAMES.map((name,id)=>[name,id]));
CHARACTER_IMAGE_IDS.set('비요른 얀델',17);
const state={invalid:false,refreshController:null,readSession:window.CompanyReadSession.create(),readOwner:null,route:routeFromPath(location.pathname),payload:null,baselinePayload:null,config:null,pendingTimer:null,filterTimer:null,filterPollTimer:null,loading:false,detail:null,bossDetail:null,buildSort:{key:'runs',direction:'desc'},versionSort:{key:'version',direction:'desc'},platformSort:{key:'runs',direction:'desc'},modeSort:{key:'runs',direction:'desc'},bossSort:{key:'encounterKills',direction:'desc'},catalogs:{versions:new Set(),modes:new Set(),ranks:new Set()}};
const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
const elements={message:$('[data-message]'),source:$('[data-source-badge]'),refresh:$('[data-refresh]'),persistence:$('[data-persistence]'),persistenceDot:$('[data-persistence-dot]'),routeTitle:$('[data-route-title]'),dateFrom:$('#dateFrom'),dateTo:$('#dateTo'),version:$('#versionFilter'),mode:$('#modeFilter'),modeLevel:$('#modeLevelMin'),afterFirstMiddleBoss:$('#afterFirstMiddleBoss'),trend:$('#trendChart'),trendTooltip:$('[data-trend-tooltip]'),content:$('#main'),filterApplyState:$('[data-filter-apply-state]'),analysisLoading:$('[data-analysis-loading]'),analysisLoadingLabel:$('[data-analysis-loading-label]')};

document.addEventListener('workspace-entity-scope-change', invalidateStatistics);
window.addEventListener('pagehide', event => { if (!event.persisted) { state.invalid=true; stopDataRequests(); state.readSession.dispose(); state.refreshController?.dispose(); } });
initializeHelpTips();
initialize();

function initializeHelpTips(){for(const tip of $$('.help-tip'))tip.removeAttribute('title')}

async function initialize(){setPeriod(7,false);bindRouting();bindGlobalFilters();bindDetailFilters();applyRoute();const result=await state.readSession.run('statistics-bootstrap',signal=>fetchJson('/api/config',{signal}),30_000);if(state.invalid||result.status==='cancelled'||!result.isCurrent())return;if(result.status==='error'){showMessage(result.error.message,true);return}state.config=result.value;renderStorageStatus(state.config);renderPublication(state.config.publication);initializeRefresh();await loadData()}
function stopDataRequests(){state.readOwner=null;state.readSession.cancel('statistics-overview');clearTimeout(state.filterTimer);clearTimeout(state.filterPollTimer);state.loading=false;endFilterLoading()}
function invalidateStatistics(){state.invalid=true;stopDataRequests();state.readSession.dispose();state.payload=null;state.baselinePayload=null;for(const page of $$('[data-page]'))page.classList.add('hidden');setSourceStatus('계정 확인 필요','warning')}
function initializeRefresh(){
  state.refreshController=attachStatisticsRefresh({button:elements.refresh,statusNode:$('[data-refresh-state]'),user:state.config.currentUser,
    onPublication:renderPublication,onBoundary:stopDataRequests,onInvalidate:invalidateStatistics,
    onIdle:()=>{if(state.queuedRead){state.queuedRead=false;void loadData();}},
    onComplete:(isCurrent,publication)=>loadData(isCurrent,publication)});
  if(state.config.publication?.inProgress)state.refreshController.startPolling();
}

function bindRouting(){document.addEventListener('click',event=>{const link=event.target.closest('a[data-route-link]');if(!link||event.defaultPrevented||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||link.target||link.hasAttribute('download'))return;const url=new URL(link.href,location.href);if(url.origin!==location.origin)return;event.preventDefault();navigate(url.pathname+url.search+url.hash)});window.addEventListener('popstate',()=>{state.route=routeFromPath(location.pathname);applyRoute();void loadData()})}
function bindGlobalFilters(){for(const button of $$('[data-days]'))button.addEventListener('click',()=>setPeriod(Number(button.dataset.days),true));elements.dateFrom.addEventListener('change',customRangeChanged);elements.dateTo.addEventListener('change',customRangeChanged);elements.version.addEventListener('change',scheduleLoadData);elements.mode.addEventListener('change',modeChanged);elements.modeLevel.addEventListener('change',scheduleLoadData);elements.afterFirstMiddleBoss.addEventListener('change',requestFilterLoad)}
function bindDetailFilters(){for(const id of ['resultSearch','resultMinRuns'])$('#'+id).addEventListener(id==='resultSearch'?'input':'change',renderResults);$('#buildType').addEventListener('change',buildTypeChanged);for(const button of $$('[data-build-type]'))button.addEventListener('click',()=>selectBuildType(button.dataset.buildType));$('#buildSearch').addEventListener('input',renderBuilds);$('#combinationNodes').addEventListener('change',requestFilterLoad);$('[data-build-detail-back]').addEventListener('click',()=>navigate('/builds'));$('[data-boss-detail-back]').addEventListener('click',()=>navigate('/bosses'));for(const button of $$('[data-build-sort]'))button.addEventListener('click',()=>changeSort('build',button.dataset.buildSort,renderBuilds));for(const button of $$('[data-version-sort]'))button.addEventListener('click',()=>changeSort('version',button.dataset.versionSort,renderResults));for(const button of $$('[data-platform-sort]'))button.addEventListener('click',()=>changeSort('platform',button.dataset.platformSort,renderResults));for(const button of $$('[data-mode-sort]'))button.addEventListener('click',()=>changeSort('mode',button.dataset.modeSort,renderResults));for(const id of ['bossSearch','bossRank','bossMinKills','bossMaxDuration','bossLinked'])$('#'+id).addEventListener(id==='bossSearch'?'input':'change',renderBosses);for(const button of $$('[data-boss-sort]'))button.addEventListener('click',()=>changeSort('boss',button.dataset.bossSort,renderBosses))}
function routeFromPath(path){return Object.entries(ROUTES).find(([,route])=>[route.path,...route.aliases||[]].includes(path))?.[0]||'dashboard'}
function applyRoute(){if(state.invalid)return;for(const page of $$('[data-page]'))page.classList.toggle('hidden',page.dataset.page!==state.route);elements.routeTitle.textContent=ROUTES[state.route].title;document.title=`${ROUTES[state.route].title} · Game Pulse`;document.dispatchEvent(new CustomEvent('company-route-change'));if(state.route==='buildDetail')renderBuildDetail();if(state.route==='bossDetail')renderBossDetail();scrollTo({top:0,behavior:'instant'})}

function setPeriod(days,reload){const now=new Date();const from=new Date(now);from.setDate(from.getDate()-(days-1));elements.dateFrom.value=localDateKey(from);elements.dateTo.value=localDateKey(now);for(const button of $$('[data-days]'))button.setAttribute('aria-pressed',String(Number(button.dataset.days)===days));if(reload)requestFilterLoad()}
function customRangeChanged(){for(const button of $$('[data-days]'))button.setAttribute('aria-pressed','false');requestFilterLoad()}
function modeChanged(){const mode=String(elements.mode.value||'').toLowerCase();elements.modeLevel.value=mode.includes('challenge')||mode.includes('도전')?'5':'';scheduleLoadData()}
function requestFilterLoad(){beginFilterLoading();loadData()}
function scheduleLoadData(){beginFilterLoading();clearTimeout(state.filterTimer);state.filterTimer=setTimeout(()=>loadData(),220)}
function scheduleFilterPoll(delay=2000){clearTimeout(state.filterPollTimer);state.filterPollTimer=setTimeout(()=>loadData(),delay)}
function beginFilterLoading(){const description=currentFilterDescription();elements.content.setAttribute('aria-busy','true');elements.analysisLoading.classList.remove('hidden');elements.filterApplyState.classList.remove('hidden');elements.analysisLoadingLabel.textContent=`${description} 통계를 불러오는 중입니다.`;elements.filterApplyState.querySelector('span').textContent='필터 적용 중'}
function endFilterLoading(){elements.content.removeAttribute('aria-busy');elements.analysisLoading.classList.add('hidden');elements.filterApplyState.classList.add('hidden')}
function currentFilterDescription(){const parts=[elements.version.value||'전체 버전',elements.mode.value||'전체 모드'];if(elements.modeLevel.value!=='')parts.push(`${elements.modeLevel.value}단계 이상`);parts.push(elements.afterFirstMiddleBoss.checked?'1챕터 중간보스 이후':'전체 진행도');return parts.join(' · ')}
function queryRange(){const from=new Date(`${elements.dateFrom.value}T00:00:00`);let to=new Date(`${elements.dateTo.value}T23:59:59.999`);const now=new Date();if(to>now)to=now;if(Number.isNaN(from.getTime())||Number.isNaN(to.getTime())||from>=to)throw new Error('조회 시작일과 종료일을 확인해 주세요.');return{from,to}}

async function loadData(isAllowed=()=>true,expectedPublication=null){
  if(state.invalid||!isAllowed())return false;
  if(state.refreshController?.pending){state.queuedRead=true;endFilterLoading();return false;}
  clearTimeout(state.filterTimer);clearTimeout(state.filterPollTimer);beginFilterLoading();
  state.readSession.cancel('statistics-overview');const owner=Symbol('statistics-overview');state.readOwner=owner;state.loading=true;
  const isCurrent=()=>!state.invalid&&state.readOwner===owner&&isAllowed();
  let result;
  try{
    const range=queryRange(),query=new URLSearchParams({from:range.from.toISOString(),to:range.to.toISOString()});
    appendViewQuery(query);if(elements.version.value)query.set('version',elements.version.value);if(elements.mode.value)query.set('mode',elements.mode.value);if(elements.modeLevel.value!=='')query.set('minModeLevel',elements.modeLevel.value);if(elements.afterFirstMiddleBoss.checked)query.set('afterFirstMiddleBoss','1');if($('#buildType').value==='combinations'&&$('#combinationNodes').checked)query.set('includeNodes','1');
    result=await state.readSession.run('statistics-overview',async signal=>readStatisticsOverview(await fetchJson(`/api/analytics/overview?${query}`,{signal})),30_000);if(!isCurrent()||result.status==='cancelled'||!result.isCurrent())return false;if(result.status==='error')throw result.error;const payload=result.value;
    if(expectedPublication&&(payload.publishedAt!==expectedPublication.completedAt||payload.publication?.runId!==expectedPublication.runId||payload.publication?.status!=='ready'))throw Error('완료된 집계와 조회 결과의 기준이 다릅니다. 최신 상태를 다시 확인해 주세요.');
    hydrateMasterData(payload);state.payload=payload;if(!elements.version.value)state.baselinePayload=payload;collectCatalogs(payload);renderAll();endFilterLoading();clearMessage();return true;
  }catch(error){
    if(error.name!=='AbortError'&&isCurrent()){const keepingCurrent=Boolean(state.payload);showMessage(keepingCurrent?`${error.message} 현재 표시 중인 마지막 완료 집계는 유지합니다.`:error.message,error.status!==425);if(error.status===425)scheduleFilterPoll();else endFilterLoading()}
    return false;
  }finally{if(state.readOwner===owner){state.loading=false;state.readOwner=null}}
}

function appendViewQuery(query){query.set('view',state.route);if(state.route==='builds')query.set('buildType',$('#buildType').value||'characters');if(state.route==='buildDetail'){const params=new URLSearchParams(location.search),type=state.detail?.type||params.get('type')||'characters';query.set('buildType',type);query.set('detailKey',String(state.detail?.item?.key||state.detail?.item?.name||params.get('key')||''))}if(state.route==='bossDetail'){const params=new URLSearchParams(location.search);query.set('detailKey',String(state.bossDetail?.key||state.bossDetail?.id||state.bossDetail?.name||params.get('key')||''))}}

function hydrateMasterData(payload){const bosses=state.config?.masterData?.bosses||[];payload.bosses=(payload.bosses||[]).map(item=>{const normalized=String(item.name||'').trim().toLocaleLowerCase('ko-KR').replace(/\s+/g,' '),master=bosses.find(candidate=>candidate.code===item.code||String(candidate.name||'').trim().toLocaleLowerCase('ko-KR').replace(/\s+/g,' ')===normalized);return master?{...item,masterId:item.masterId??master.id,code:item.code||master.code,imageCode:item.imageCode||master.imageCode,rank:item.rank||master.rank}:item})}
function collectCatalogs(payload){for(const item of payload.versions||[])if(item.version&&item.version!=='버전 미기록')state.catalogs.versions.add(item.version);for(const item of payload.dimensions?.modes||[])if(item.key&&item.key!=='모드 미기록')state.catalogs.modes.add(item.key);for(const item of payload.bosses||[])if(item.rank)state.catalogs.ranks.add(item.rank);syncVersionSelect();syncSelect(elements.mode,'전체 모드',[...state.catalogs.modes].sort(locale));syncSelect($('#bossRank'),'전체 랭크',[...state.catalogs.ranks].sort(locale))}
function syncVersionSelect(){const selected=elements.version.value,versions=[...state.catalogs.versions].sort(compareVersionDesc),families=[...new Set(versions.map(value=>String(value).match(/^(\d+)\.(\d+)\.\d+$/)?.slice(1,3)).filter(Boolean).map(([major,minor])=>`${major}.${minor}.x`))].sort(compareVersionDesc);elements.version.replaceChildren(option('','전체 버전'),...families.map(value=>option(value,`${value} · 패치 전체`)),...versions.map(value=>option(value,value)));elements.version.value=[...families,...versions].includes(selected)?selected:''}
function syncSelect(select,allLabel,values){const selected=select.value;select.replaceChildren(option('',allLabel),...values.map(value=>option(value,value)));select.value=values.includes(selected)?selected:''}

function renderAll(){const payload=state.payload||{};if(state.route==='dashboard')renderDashboard(payload);else if(state.route==='results')renderResults();else if(state.route==='builds')renderBuilds();else if(state.route==='bosses')renderBosses();else if(state.route==='buildDetail')renderBuildDetail();else if(state.route==='bossDetail')renderBossDetail();$('[data-updated]').textContent=`집계 완료 ${formatDateTime(payload.publishedAt||payload.generatedAt)}`;setSourceStatus(payload.mode==='demo'?'DEMO DATA':lastAggregationLabel(),payload.mode==='demo'?'warning':'success')}
function renderDashboard(payload){const summary=payload.summary||{};setText('[data-kpi="activePlayers"]',formatNumber(summary.activePlayers));setText('[data-kpi="totalRuns"]',formatNumber(summary.totalRuns));setText('[data-kpi="completionRate"]',formatPercent(summary.completionRate));setText('[data-kpi="deathRate"]',formatPercent(summary.deathRate));setText('[data-kpi="bossKills"]',formatNumber(summary.bossKills));setText('[data-kpi="playTime"]',formatDuration(summary.playTime?.medianMs));setText('[data-kpi-note="completionRate"]',`${formatNumber(summary.gameCompletions)} Run 클리어`);setText('[data-kpi-note="deathRate"]',`${formatNumber((payload.outcomes||[]).find(item=>item.key==='Dead')?.count)} Run 사망`);setText('[data-kpi-note="playTime"]',`중앙값 · P90 ${formatDuration(summary.playTime?.p90Ms)}`);renderTrend(payload.trend||[]);renderOutcomeCards($('[data-dashboard-outcomes]'),payload.outcomes||[],true);renderRankList($('[data-dashboard-builds]'),payload.builds?.characters||[],'characters',item=>({name:item.name,meta:`${formatNumber(item.runs)} Run · 클리어 ${formatPercent(item.clearRate)}`,value:formatPercent(item.selectionRate)}));renderRankList($('[data-dashboard-bosses]'),payload.bosses||[],'bosses',item=>({name:item.name,meta:`${formatNumber(item.uniquePlayers)}명 · 중앙 ${formatDuration(item.fightDuration?.medianMs)}`,value:formatNumber(item.killCount)}));renderQuality(payload.schema||{},payload.schemaCutoverVersion)}
function renderTrend(items){elements.trend.replaceChildren();hideTrendTooltip();if(!items.length){appendSvgText(elements.trend,'집계된 추이 데이터가 없습니다.',430,150);return}const width=860,height=300,inset={top:20,right:20,bottom:38,left:48};const max=Math.max(1,...items.flatMap(item=>[item.players||0,item.clears||0]));const step=(width-inset.left-inset.right)/Math.max(1,items.length-1),x=i=>inset.left+i*step,y=value=>height-inset.bottom-(Number(value||0)/max)*(height-inset.top-inset.bottom);for(let i=0;i<4;i++){const value=max*(1-i/3),lineY=y(value);elements.trend.append(svg('line',{x1:inset.left,y1:lineY,x2:width-inset.right,y2:lineY,class:'chart-grid'}));const label=svg('text',{x:inset.left-9,y:lineY+4,class:'chart-label','text-anchor':'end'});label.textContent=compactNumber(value);elements.trend.append(label)}const players=items.map((item,i)=>`${x(i)},${y(item.players)}`).join(' '),clears=items.map((item,i)=>`${x(i)},${y(item.clears)}`).join(' ');elements.trend.append(svg('polygon',{points:`${players} ${x(items.length-1)},${height-inset.bottom} ${x(0)},${height-inset.bottom}`,class:'chart-area'}),svg('polyline',{points:players,class:'chart-line players'}),svg('polyline',{points:clears,class:'chart-line clears'}));items.forEach((item,i)=>{elements.trend.append(svg('circle',{cx:x(i),cy:y(item.players),r:3,class:'chart-point players'}),svg('circle',{cx:x(i),cy:y(item.clears),r:3,class:'chart-point clears'}));const hit=svg('rect',{x:Math.max(inset.left,x(i)-Math.max(12,step/2)),y:inset.top,width:Math.min(Math.max(24,step),width-inset.right-Math.max(inset.left,x(i)-Math.max(12,step/2))),height:height-inset.top-inset.bottom,class:'chart-hit',tabindex:'0','aria-label':`${item.date} 활성 플레이어 ${formatNumber(item.players)}, 클리어 ${formatNumber(item.clears)}, 출정 ${formatNumber(item.runs)}`});hit.addEventListener('pointerenter',event=>showTrendTooltip(event,item));hit.addEventListener('pointermove',event=>positionTrendTooltip(event));hit.addEventListener('pointerleave',hideTrendTooltip);hit.addEventListener('focus',event=>showTrendTooltip(event,item));hit.addEventListener('blur',hideTrendTooltip);elements.trend.append(hit);if(items.length<=14||i%Math.ceil(items.length/8)===0||i===items.length-1){const label=svg('text',{x:x(i),y:height-12,class:'chart-label','text-anchor':'middle'});label.textContent=item.date;elements.trend.append(label)}})}
function showTrendTooltip(event,item){elements.trendTooltip.replaceChildren(el('strong',{},item.date),el('span',{},`활성 플레이어 ${formatNumber(item.players)}`),el('span',{},`클리어 ${formatNumber(item.clears)}`),el('span',{},`출정 ${formatNumber(item.runs)}`));elements.trendTooltip.classList.remove('hidden');positionTrendTooltip(event)}
function positionTrendTooltip(event){if(elements.trendTooltip.classList.contains('hidden'))return;const wrap=elements.trend.parentElement,rect=wrap.getBoundingClientRect(),clientX=Number.isFinite(event.clientX)?event.clientX:rect.left+rect.width/2,clientY=Number.isFinite(event.clientY)?event.clientY:rect.top+rect.height/2;elements.trendTooltip.style.left=`${Math.max(100,Math.min(rect.width-100,clientX-rect.left))}px`;elements.trendTooltip.style.top=`${Math.max(8,clientY-rect.top-92)}px`}
function hideTrendTooltip(){elements.trendTooltip.classList.add('hidden')}
function renderOutcomeCards(container,items,compact=false){container.replaceChildren();for(const item of items.filter(item=>item.key!=='Unknown'||item.count)){const row=document.createElement('div');row.className='outcome-card';row.dataset.key=item.key;row.append(el('span',{},item.label),el('strong',{},formatPercent(item.rate)));const track=el('div',{class:'mini-track'});const bar=document.createElement('i');bar.style.width=`${clamp(item.rate)}%`;track.append(bar);row.append(track);if(!compact)row.append(el('small',{},`${formatNumber(item.count)} Run`));container.append(row)}if(!container.children.length)container.append(emptyBlock('결과 데이터가 없습니다.'))}
function renderRankList(container,items,type,map){container.replaceChildren();items.slice(0,5).forEach((item,index)=>{const value=map(item),row=el('div',{class:'rank-item with-image'});row.append(el('b',{},String(index+1)),createEntityVisual(type,item,value.name));const identity=el('div',{});identity.append(el('strong',{},value.name||'미기록'),el('small',{},value.meta));row.append(identity,el('span',{},value.value));container.append(row)});if(!container.children.length)container.append(emptyBlock('집계 데이터가 없습니다.'))}
function renderQuality(schema,cutover){const container=$('[data-dashboard-quality]');container.replaceChildren();const items=[['구조화 로그',schema.structuredRate||0,`${formatNumber(schema.v2Events)}건`],['보스 Run 연결',schema.bossLinkRate||0,`${formatNumber(schema.linkedBossKills)}건`],['구버전 이름 로그',schema.totalEvents?schema.legacyEvents/schema.totalEvents*100:0,`${formatNumber(schema.legacyEvents)}건`]];for(const [label,rate,count] of items){const row=el('div',{class:'quality-line'});row.append(el('span',{},label),el('strong',{},`${formatPercent(rate)} · ${count}`));const track=el('div',{class:'quality-track'}),bar=document.createElement('i');bar.style.width=`${clamp(rate)}%`;track.append(bar);row.append(track);container.append(row)}container.append(el('small',{},`개선 로그 기준 ${cutover||'0.772.0'} · 구버전은 이름 기준 집계`))}

function renderResults(){if(!state.payload)return;const payload=state.payload,summary=payload.summary||{},outcomes=payload.outcomes||[];const metrics=$('[data-result-metrics]');metrics.replaceChildren(metricCard('전체 Run',formatNumber(summary.totalRuns),'battle_result 표본'),metricCard('클리어',formatPercent(summary.completionRate),`${formatNumber(outcomes.find(item=>item.key==='Clear')?.count)} Run`),metricCard('사망',formatPercent(summary.deathRate),`${formatNumber(outcomes.find(item=>item.key==='Dead')?.count)} Run`),metricCard('실패·중단',formatPercent(outcomes.find(item=>item.key==='Fail')?.rate),`${formatNumber(outcomes.find(item=>item.key==='Fail')?.count)} Run`));renderOutcomeBars(outcomes);const play=$('[data-playtime]'),dist=summary.playTime||{};play.replaceChildren(distributionCell('평균',dist.averageMs),distributionCell('중앙값',dist.medianMs),distributionCell('P90',dist.p90Ms));renderVersions(payload.versions||[]);renderDimensionRows($('[data-platform-rows]'),payload.dimensions?.platforms||[],'platform');renderDimensionRows($('[data-mode-rows]'),payload.dimensions?.modes||[],'mode');renderSchemaDetail(payload.schema||{},payload.schemaCutoverVersion)}
function renderOutcomeBars(items){const container=$('[data-result-outcomes]');container.replaceChildren();for(const item of items){const row=el('div',{class:'outcome-row'});row.dataset.key=item.key;row.append(el('span',{},item.label));const track=el('div',{class:'bar-track'}),bar=document.createElement('i');bar.style.width=`${clamp(item.rate)}%`;track.append(bar);row.append(track,el('strong',{},`${formatNumber(item.count)} · ${formatPercent(item.rate)}`));container.append(row)}}
function renderVersions(items){const search=$('#resultSearch').value.trim().toLowerCase(),min=numberValue($('#resultMinRuns').value);let rows=items.filter(item=>item.version.toLowerCase().includes(search)&&item.runs>=min);rows.sort(versionSorter(state.versionSort.key,state.versionSort.direction));const body=$('[data-version-rows]');body.replaceChildren();for(const item of rows){const row=document.createElement('tr');row.append(cell(item.version,'entity'),numberCell(item.players),numberCell(item.runs),rateCell(item.clears,item.clearRate,'number positive'),rateCell(item.deaths,item.deathRate,'number negative'),numberCell(item.fails),cell(formatDuration(item.playTime?.medianMs),'number'));body.append(row)}if(!rows.length)emptyTable(body,7,'조건에 맞는 버전이 없습니다.');setText('[data-result-count]',`${formatNumber(rows.length)}개 버전`);updateSortHeaders('version')}
