function openBossDetail(boss){state.bossDetail=boss;const query=new URLSearchParams({key:boss.key||boss.id||boss.name||''});navigate(`/bosses/detail?${query}`)}
function resolveBossDetail(){const key=String(state.bossDetail?.key||new URLSearchParams(location.search).get('key')||'');return(state.payload?.bosses||[]).find(boss=>String(boss.key||boss.id||boss.name||'')===key)||null}
function renderBossDetail(){if(!state.payload)return;const boss=resolveBossDetail(),identity=$('[data-boss-detail-identity]'),summary=$('[data-boss-detail-summary]'),loadouts=$('[data-boss-detail-loadouts]'),combinations=$('[data-boss-detail-combinations]');if(!boss){setText('[data-boss-detail-title]','보스를 찾을 수 없습니다');setText('[data-boss-detail-subtitle]','현재 조회 조건에서 제외된 보스입니다.');identity.replaceChildren(emptyBlock('보스 분석으로 돌아가 다시 선택해 주세요.'));summary.replaceChildren();loadouts.replaceChildren();combinations.replaceChildren();return}state.bossDetail=boss;setText('[data-boss-detail-title]',boss.name||'알 수 없는 보스');setText('[data-boss-detail-subtitle]',`${boss.rank||'랭크 미기록'} · 조우 시점 빌드를 분모로 사용한 처치 성과입니다.`);identity.replaceChildren();const identityCell=el('div',{class:'detail-identity'});appendEntityIdentity(identityCell,'bosses',boss,boss.name||'알 수 없는 보스',boss.rank||'');identity.append(identityCell);summary.replaceChildren(metricCard('조우',formatNumber(boss.encounterCount||0),'신규 조우 로그'),metricCard('조우 후 처치',formatNumber(bossEncounterKills(boss)),'조우→처치율 분자'),metricCard('조우→처치율',boss.encounterClearRate==null?'—':formatPercent(boss.encounterClearRate),'조우 후 처치 ÷ 조우'),metricCard('전체 처치 로그',formatNumber(boss.killCount||0),'조우 로그가 없는 구버전 포함'),metricCard('중앙 전투 시간',formatDuration(boss.fightDuration?.medianMs),`${formatNumber(boss.fightDuration?.sampleSize||0)}개 신뢰 표본`));renderBossBuildPanels(loadouts,boss);renderBossCombinations(combinations,boss.buildStats?.combinations||[])}
function renderBossBuildPanels(container,boss){container.replaceChildren();const labels={characters:'캐릭터',skins:'스킨',weapons:'무기+고유룬',pets:'펫',skills:'스킬',artifacts:'유물'};for(const[type,label]of Object.entries(labels)){const panel=el('section',{class:'loadout-panel'}),header=el('header',{}),items=boss.buildStats?.[type]||[];header.append(el('h3',{},label),el('span',{},`${formatNumber(items.length)}개 기록`));panel.append(header);const rows=el('div',{class:'loadout-rows'});for(const item of items.slice(0,8)){const row=el('div',{class:`loadout-row${type==='weapons'?' weapon-loadout-row':''}`}),text=el('span',{}),rate=item.clearRate==null?'처치율 —':`처치율 ${formatPercent(item.clearRate)}`,matchedKills=Number(item.matchedKills||0),result=el('b',{class:item.clearRate!=null?'positive':'warning'},`${formatNumber(matchedKills)} 처치 · ${rate}`),visual=type==='weapons'?createWeaponVisuals(item):createEntityVisual(type,item,item.name);if(type==='weapons')for(const rune of displayRunes(item))visual.append(createRuneBadge(rune,true));if(Number(item.kills||0)!==matchedKills)result.title=`전체 처치 로그 ${formatNumber(item.kills||0)}건`;row.append(visual);text.append(el('strong',{},type==='weapons'?weaponDisplayName(item):item.name||'미기록'),el('small',{},`${type==='weapons'?`${weaponRuneStatus(item)} · `:''}${formatNumber(item.encounters)}회 조우 · 채택 ${item.encounterAdoptionRate==null?'—':formatPercent(item.encounterAdoptionRate)}`));row.append(text,result);rows.append(row)}if(!items.length)rows.append(emptyBlock('해당 빌드 기록이 없습니다.'));panel.append(rows);container.append(panel)}}
function renderBossCombinations(container,items){container.replaceChildren();for(const item of items.filter(value=>Number(value.matchedKills||0)>0).slice(0,20)){const row=el('div',{class:'character-combination-row'}),identity=el('span',{class:'combination-visuals'}),stats=el('span',{class:'combination-stats'}),matchedKills=Number(item.matchedKills||0);if(item.character)identity.append(createEntityVisual('characters',item.character,item.character.name));if(item.skin)identity.append(createEntityVisual('skins',item.skin,item.skin.name));for(const weapon of item.weapons||[])identity.append(createEntityVisual('weapons',weapon,weapon.name));if(item.pet)identity.append(createEntityVisual('pets',item.pet,item.pet.name));appendCombinationSlots(identity,'skills',item.skills,6,'빈 스킬');appendCombinationSlots(identity,'artifacts',item.artifacts,6,'빈 유물');stats.append(el('strong',{},`${formatNumber(matchedKills)}회 조우 후 처치 · ${formatNumber(item.encounters)}회 조우`),el('small',{},`조우 채택 ${formatPercent(item.encounterAdoptionRate)} · 처치율 ${formatPercent(item.clearRate)}`));if(Number(item.kills||0)!==matchedKills)stats.title=`전체 처치 로그 ${formatNumber(item.kills||0)}건`;row.append(identity,stats);container.append(row)}if(!container.children.length)container.append(emptyBlock('조우 로그에 연결된 보스 처치 조합이 없습니다.'))}

function bossEncounterKills(boss){return Number(boss?.encounterKillCount??boss?.matchedKills??0)}

function appendEntityIdentity(container,type,item,title,meta){container.classList.add('entity-identity');container.append(createEntityVisual(type,item,title));const labels=el('span',{class:'entity-labels'});labels.append(el('strong',{},title));if(meta)labels.append(el('small',{},meta));container.append(labels)}
function createEntityVisual(type,item,title){const visual=el('span',{class:'entity-visual','aria-label':String(title||'')},String(title||'?').trim().slice(0,1)||'?'),src=entityImagePath(type,item);if(src){const image=el('img',{src,alt:'',loading:'lazy'});image.addEventListener('error',()=>image.remove(),{once:true});visual.append(image)}return visual}
function entityImagePath(type,item){if(type==='characters'){const namedId=CHARACTER_IMAGE_IDS.get(String(item.name||'').trim()),hasId=item.id!==null&&item.id!==undefined&&item.id!=='',numericId=hasId?Number(item.id):NaN,id=namedId!==undefined?namedId:Number.isInteger(numericId)&&numericId>=0&&numericId<=21?numericId:undefined;return id===undefined?'':`/assets/entities/characters/${id}.png?v=face-v2`}if(type==='skins'){const characterId=Number(item.characterId),skinId=Number(item.id);return Number.isInteger(characterId)&&characterId>=0&&characterId<=21&&Number.isInteger(skinId)&&skinId>=0?`/assets/entities/skins/${characterId}/${skinId}.png?v=skin-v1`:''}if(type==='weapons'){const characterId=Number(item.characterId),weaponId=Number(item.id);return Number.isInteger(characterId)&&characterId>=0&&characterId<=21&&Number.isInteger(weaponId)&&weaponId>=0?`/assets/entities/weapons/${characterId}/${weaponId}.png?v=weapon-v2`:''}if(type==='nodes'){const characterId=Number(item.characterId),nodeId=Number(item.id);return Number.isInteger(characterId)&&characterId>=0&&characterId<=21&&Number.isInteger(nodeId)&&nodeId>=0?`/assets/entities/nodes/${characterId}/${nodeId}.png?v=node-v1`:''}if(type==='pets'){const id=Number(item.id);return Number.isInteger(id)&&id>=0&&id<=37?`/assets/entities/pets/${id}.png?v=pet-v2`:''}if(type==='skills'){const id=Number(item.id);return Number.isInteger(id)&&id>=0&&id<=105?`/assets/entities/skills/${id}.png`:''}if(type==='artifacts'){const key=String(item.sourceKey||item.key||''),match=key.match(/(?:^|:)(\d+)$/);return match?`/assets/entities/artifacts/${item.cursed?'curse':'normal'}-${Number(match[1])}.png`:''}if(type==='bosses'){const rawId=String(item.id||'').toUpperCase(),imageCode=String(item.imageCode||(/^[BE]\d+$/.test(rawId)?rawId:'')).toUpperCase();return /^[BE]\d+(?:_\d+)?$/.test(imageCode)?`/assets/entities/bosses/${imageCode}.png`:''}return''}

function setSourceStatus(text,tone){elements.source.className='source-badge cw-state-pill';elements.source.dataset.tone=tone;elements.source.textContent=text}
function renderStorageStatus(config){setSourceStatus(config.storageConfigured?'집계 시각 확인 중':'DEMO DATA',config.storageConfigured?'neutral':'warning');const persistence=config.sync?.persistence==='azure'||config.processedStorageConfigured;elements.persistence.textContent=persistence?'Azure 영속 저장':'로컬 캐시';elements.persistenceDot.classList.toggle('live',persistence)}
function renderPublication(publication){if(!publication)return;if(state.config)state.config.publication=publication;const last=lastAggregationLabel(publication.completedAt);if(publication.status==='error'){setSourceStatus(`갱신 오류 · ${last}`,'danger');return}if(publication.inProgress){const progress=publication.totalProfiles?`${formatNumber(publication.publishedProfiles)}/${formatNumber(publication.totalProfiles)} · `:'';setSourceStatus(`집계 중 ${progress}${last}`,'info');return}setSourceStatus(last,'success')}
function lastAggregationLabel(fallback=''){const value=state.payload?.publishedAt||state.payload?.generatedAt||fallback||state.config?.publication?.completedAt;return value?`마지막 집계 ${formatDateTime(value)}`:'마지막 집계 확인 중'}

function metricCard(label,value,note){const card=el('article',{class:'metric-card'});card.append(el('span',{},label),el('strong',{},value),el('small',{},note));return card}function distributionCell(label,value){const node=document.createElement('div');node.append(el('span',{},label),el('strong',{},formatDuration(value)),el('small',{},'기록된 표본 기준'));return node}function schemaCard(label,value,headline,note,tone){const node=el('div',{class:'schema-stat'});node.append(el('span',{},label),el('strong',{class:tone},typeof value==='number'?formatNumber(value):value),el('small',{},`${headline} · ${note}`));return node}function rateCell(count,rate,tone){return cell(`${formatNumber(count)} · ${formatPercent(rate)}`,tone)}function cell(text,className=''){const classes=className.split(/\s+/),tone=classes.some(value=>['positive','good'].includes(value))?'success':classes.some(value=>['negative','low'].includes(value))?'danger':classes.some(value=>['warning','medium'].includes(value))?'warning':null;return el('td',{class:className,'data-tone':tone},text)}function numberCell(value){return cell(formatNumber(value),'number')}function emptyTable(body,columns,text){const row=document.createElement('tr'),td=cell(text,'empty');td.colSpan=columns;row.append(td);body.append(row)}function emptyBlock(text){return el('p',{class:'empty'},text)}
function el(tag,attrs={},text=''){const node=document.createElement(tag);for(const[key,value]of Object.entries(attrs))if(value)node.setAttribute(key,value);if(text!==undefined&&text!==null)node.textContent=text;return node}function option(value,text){const node=document.createElement('option');node.value=value;node.textContent=text;return node}function setText(selector,text){const node=$(selector);if(node)node.textContent=text}function svg(name,attrs){const node=document.createElementNS('http://www.w3.org/2000/svg',name);for(const[key,value]of Object.entries(attrs))node.setAttribute(key,value);return node}function appendSvgText(parent,text,x,y){const node=svg('text',{x,y,class:'chart-label','text-anchor':'middle'});node.textContent=text;parent.append(node)}
function showMessage(text,error){if(state.invalid)return;elements.message.classList.remove('hidden');window.CompanyState.render(elements.message,{kind:error?'error':'loading',title:error?'통계를 불러오지 못했습니다.':'통계를 준비하고 있습니다.',message:text})}function clearMessage(){elements.message.classList.add('hidden')}
async function fetchJson(url,init={}){const response=await fetch(url,{...init,credentials:'same-origin',redirect:'manual',cache:'no-store',headers:{...init.headers,'X-Statistics-Return-Url':location.pathname+location.search}});if(init.signal?.aborted)throw new DOMException('Aborted','AbortError');if(response.type==='opaqueredirect'||!String(response.headers.get('content-type')||'').includes('application/json'))throw Object.assign(new Error('서버 응답 형식을 확인하지 못했습니다.'),{status:response.status});let payload;try{payload=await response.json()}catch{throw Object.assign(new Error('서버 JSON 응답을 해석하지 못했습니다.'),{status:response.status})}if(init.signal?.aborted)throw new DOMException('Aborted','AbortError');if(response.status===401&&payload.loginUrl){window.CompanyWorkspace?.sessionExpired?.(payload.loginUrl);throw Object.assign(new Error('회사 계정 로그인이 필요합니다.'),{status:401})}if(!response.ok){const error=new Error(payload.error||`요청에 실패했습니다. (HTTP ${response.status})`);error.status=response.status;error.payload=payload;throw error}return payload}
function formatNumber(value){return new Intl.NumberFormat('ko-KR').format(Number(value||0))}function formatPercent(value){return`${Number(value||0).toLocaleString('ko-KR',{maximumFractionDigits:1})}%`}function formatSignedPercent(value){const number=Number(value||0);return`${number>0?'+':''}${number.toLocaleString('ko-KR',{maximumFractionDigits:1})}%p`}function formatDuration(ms){if(ms===null||ms===undefined||!Number.isFinite(Number(ms)))return'—';const seconds=Math.round(Number(ms)/1000);return seconds>=3600?`${Math.floor(seconds/3600)}시간 ${Math.floor(seconds%3600/60)}분`:seconds>=60?`${Math.floor(seconds/60)}분 ${seconds%60}초`:`${seconds}초`}function formatDateTime(value){if(!value)return'—';return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value))}function compactNumber(value){return new Intl.NumberFormat('ko-KR',{notation:'compact',maximumFractionDigits:1}).format(Number(value||0))}function localDateKey(date){const offset=date.getTimezoneOffset()*60000;return new Date(date.getTime()-offset).toISOString().slice(0,10)}function numberValue(value){const number=Number(value);return Number.isFinite(number)?number:0}function clamp(value){return Math.max(0,Math.min(100,Number(value||0)))}function locale(a,b){return String(a).localeCompare(String(b),'ko')}function compareVersionDesc(a,b){const parse=value=>String(value).match(/\d+/g)?.map(Number)||[];const left=parse(a),right=parse(b);for(let i=0;i<Math.max(left.length,right.length);i++){const diff=(right[i]||0)-(left[i]||0);if(diff)return diff}return locale(b,a)}
